suggestions.sketch:
Create a new class CustomerDescriptionBuilder that takes a Customer and returns the formatted string. Move the describe_customer method into it. Create a new class MailSummaryService that takes an EmailClient and an OrderRepository and implements mail_summary. In ReportView, keep only title() and order_count(), delegating the other responsibilities to the helper classes. Example:

class CustomerDescriptionBuilder:
    def __init__(self, width: int = 40):
        self._width = width
    def build(self, customer) -> str:
        parts = [str(customer.customer_id()), customer.name(), customer.email(), customer.tier()]
        return " | ".join(parts).ljust(self._width)

class MailSummaryService:
    def __init__(self, repository: OrderRepository, mailer: EmailClient):
        self._repository = repository
        self._mailer = mailer
    def send_summary(self, address: str) -> dict[str, str]:
        return self._mailer.send(address, f"{self._repository.count()} orders")

class ReportView:
    def __init__(self, repository: OrderRepository, mailer: EmailClient) -> None:
        self._repository = repository
        self._mailer = mailer
        self._width = 40
        self._desc_builder = CustomerDescriptionBuilder(self._width)
        self._mail_service = MailSummaryService(repository, mailer)
    def title(self) -> str:
        return "Orders".center(self._width, "-")
    def describe_customer(self, customer) -> str:
        return self._desc_builder.build(customer)
    def order_count(self) -> int:
        return self._repository.count()
    def mail_summary(self, address: str) -> dict[str, str]:
        return self._mail_service.send_summary(address)

